    /**
     * Method to retrieve the Operation via OperationFetchOneSummary
     * @param 	summary OperationFetchOneSummary 
     * @return 	OperationFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Operation getOperation( OperationFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "OperationFetchOneSummary arg cannot be null" );
    	
    	Operation entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Operation
        	// --------------------------------------
        	CompletableFuture<Operation> futureEntity = queryGateway.query(new FindOperationQuery( new LoadOperationFilter( summary.getOperationId() ) ), ResponseTypes.instanceOf(Operation.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Operation with id " + summary.getOperationId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


